[L41]  *                     items:
[L42]  *                       type: integer
[L43]  *           example:
[L44]  *             modelId: gemma-3-12b
[L45]  *             prompt: "The capital of France is"
[L46]  *             topN: 8
[L47]  *             temperature: 0
[L48]  *             numCompletionTokens: 3
[L49]  *             activeLensModeTab: JACOBIAN_LENS
[L50]  *             hideNonWordTokens: true
[L51]  *     responses:
[L52]  *       200:
[L53]  *         description: The shared run was created successfully.
[L54]  *         content:
[L55]  *           application/json:
[L56]  *             schema:
[L57]  *               type: object
[L58]  *               properties:
[L59]  *                 id:
[L60]  *                   type: string
[L61]  *                   description: The share id.
