[L77] export const POST = withOptionalUser(async (request: RequestOptionalUser) => {
[L78]   let bodyJson;
[L79]   try {
[L80]     bodyJson = await request.json();
[L81]   } catch {
[L82]     return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
[L83]   }
[L84]
[L85]   let body;
