[L91]     }
[L92]     return NextResponse.json({ error: 'Validation error' }, { status: 400 });
[L93]   }
[L94]
[L95]   const userId = request.user?.id ?? null;
[L96]
[L97]   // Determine the run source. `inputTokenIds` (the UI's faithful-reproduction
[L98]   // path) takes precedence; otherwise the server generates from `prompt`/`chat`
[L99]   // like the `/prompt` endpoint. Exactly one of `prompt`/`chat` is required in
[L100]   // the generation path.
[L101]   const hasInputTokenIds = Array.isArray(body.inputTokenIds) && body.inputTokenIds.length > 0;
[L102]   const hasPrompt = typeof body.prompt === 'string' && body.prompt.length > 0;
[L103]   const hasChat = Array.isArray(body.chat) && body.chat.length > 0;
[L104]   if (!hasInputTokenIds && hasPrompt === hasChat) {
[L105]     return NextResponse.json({ error: "Provide exactly one of 'prompt', 'chat', or 'inputTokenIds'" }, { status: 400 });
[L106]   }
[L107]   // For the generation path, the kind follows the input given (chat vs prompt).
[L108]   // For the `inputTokenIds` path, honor the caller's `kind` (backward-compatible).
[L109]   const effectiveKind: 'chat' | 'completion' = hasInputTokenIds
[L110]     ? (body.kind as 'chat' | 'completion')
[L111]     : hasChat
[L112]       ? 'chat'
[L113]       : 'completion';
[L114]
[L115]   // Per-IP/day rate limit (mirrors the graph put-request limit).
[L116]   const headersList = await headers();
[L117]   const forwardedFor = headersList.get('x-forwarded-for');
[L118]   const ip = forwardedFor ? forwardedFor.split(',')[0].trim() : 'unknown';
[L119]
[L120]   const recentPutRequests = await prisma.jlensSharePutRequest.count({
[L121]     where: {
[L122]       ipAddress: ip,
[L123]       createdAt: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) },
[L124]     },
[L125]   });
[L126]   if (recentPutRequests >= MAX_JLENS_SHARE_PUT_REQUESTS_PER_DAY) {
[L127]     return NextResponse.json(
[L128]       { error: `Too many shares today. The maximum is ${MAX_JLENS_SHARE_PUT_REQUESTS_PER_DAY}.` },
[L129]       { status: 429 },
[L130]     );
[L131]   }
[L132]
[L133]   // Run inference server-side so the stored data is trusted (computed by us, not
[L134]   // the caller) and reproducible. Either a forced decode over the exact token
[L135]   // ids (the UI reproduction path, no generation) or a fresh generation from
[L136]   // `prompt`/`chat` (the simple API path).
[L137]   let meta: LensMetaMessage | null;
[L138]   let tokens: LensTokenMessage[];
[L139]   try {
[L140]     const inferenceResponse = await lensPromptStream(
[L141]       body.modelId,
[L142]       hasInputTokenIds
[L143]         ? {
[L144]             type: LENS_TYPE_ORDER,
[L145]             input_token_ids: body.inputTokenIds,
[L146]             top_n: body.topN,
[L147]             num_completion_tokens: 0,
[L148]             // Capture the run with the sharer's non-word filter applied, so the
[L149]             // stored blob matches what they were viewing (the share is a frozen
[L150]             // snapshot for this filter; viewers toggle by re-running live).
[L151]             filter_non_word_tokens: body.hideNonWordTokens,
[L152]           }
[L153]         : {
[L154]             type: LENS_TYPE_ORDER,
[L155]             prompt: hasChat ? undefined : body.prompt,
[L156]             chat: hasChat ? (body.chat as LensChatMessage[]) : undefined,
[L157]             top_n: body.topN,
[L158]             temperature: body.temperature,
[L159]             num_completion_tokens: body.numCompletionTokens,
[L160]             filter_non_word_tokens: body.hideNonWordTokens,
[L161]           },
[L162]     );
[L163]     if (!inferenceResponse.ok || !inferenceResponse.body) {
[L164]       const errorBody = await inferenceResponse.json().catch(() => ({ error: inferenceResponse.statusText }));
[L165]       return NextResponse.json(
[L166]         { error: errorBody.error ?? `Lens re-run failed (${inferenceResponse.status})` },
[L167]         { status: 500 },
[L168]       );
[L169]     }
[L170]     const text = await inferenceResponse.text();
[L171]     ({ meta, tokens } = await parseLensNdjson(text));
[L172]   } catch (error) {
[L173]     console.error('Error re-running lens for share:', error);
[L174]     return NextResponse.json({ error: error instanceof Error ? error.message : String(error) }, { status: 500 });
[L175]   }
[L176]
[L177]   if (!meta || tokens.length === 0) {
[L178]     return NextResponse.json({ error: 'Lens re-run produced no data' }, { status: 500 });
[L179]   }
[L180]
[L181]   // Re-run the steered read-out (if a steered run was shared) the same way: a
[L182]   // forced decode over the exact steered token ids with the steer injected and
[L183]   // no generation, so the stored steered data is trusted + reproducible (the
[L184]   // original steered generation is non-deterministic, but the ids are pinned).
[L185]   let steerExport: JlensExportSteer | undefined;
[L186]   if (body.steer) {
[L187]     try {
[L188]       const isSwap = body.steer.mode === 'swap' && !!body.steer.swapToken.trim();
[L189]       const steerResponse = await lensPromptStream(body.modelId, {
[L190]         type: LENS_TYPE_ORDER,
[L191]         input_token_ids: body.steer.inputTokenIds,
[L192]         top_n: body.topN,
[L193]         num_completion_tokens: 0,
[L194]         steer_tokens: [{ token: body.steer.token, type: body.steer.type as LensType }],
[L195]         steer_layers: body.steer.layers,
[L196]         steer_strength: body.steer.strength,
[L197]         steer_ablate: body.steer.ablate,
[L198]         swap_token: isSwap ? { token: body.steer.swapToken, type: body.steer.type as LensType } : undefined,
[L199]         steer_generated_tokens: body.steer.steerGenerated,
[L200]         filter_non_word_tokens: body.hideNonWordTokens,
[L201]       });
[L202]       if (!steerResponse.ok || !steerResponse.body) {
[L203]         const errorBody = await steerResponse.json().catch(() => ({ error: steerResponse.statusText }));
[L204]         return NextResponse.json(
[L205]           { error: errorBody.error ?? `Steered lens re-run failed (${steerResponse.status})` },
[L206]           { status: 500 },
[L207]         );
[L208]       }
[L209]       const steerText = await steerResponse.text();
[L210]       const { meta: steerMeta, tokens: steerTokens } = await parseLensNdjson(steerText);
[L211]       if (!steerMeta || steerTokens.length === 0) {
[L212]         return NextResponse.json({ error: 'Steered lens re-run produced no data' }, { status: 500 });
[L213]       }
[L214]       steerExport = {
[L215]         config: {
[L216]           token: body.steer.token,
[L217]           type: body.steer.type as LensType,
[L218]           layers: body.steer.layers,
[L219]           strength: body.steer.strength,
[L220]           ablate: body.steer.ablate,
[L221]           mode: body.steer.mode as 'steer' | 'swap',
[L222]           swapToken: body.steer.swapToken,
[L223]           steerGenerated: body.steer.steerGenerated,
[L224]         },
[L225]         meta: steerMeta,
[L226]         tokens: steerTokens,
[L227]       };
[L228]     } catch (error) {
[L229]       console.error('Error re-running steered lens for share:', error);
[L230]       return NextResponse.json({ error: error instanceof Error ? error.message : String(error) }, { status: 500 });
[L231]     }
[L232]   }
[L233]
[L234]   // Chat turns for display: the `inputTokenIds` path carries them in `messages`
[L235]   // (existing behavior); the `chat` generation path carries them in `chat`.
[L236]   const chatTurns = hasInputTokenIds ? body.messages : (body.chat ?? []);
[L237]   // For the generation path the prompt-token boundary is known from the run's
[L238]   // meta; for the reproduction path honor the caller-supplied value.
[L239]   const resolvedNumPromptTokens = hasInputTokenIds ? (body.numPromptTokens ?? null) : (meta.prompt_len ?? null);
[L240]
[L241]   // Assemble the heavy S3 blob (compact, not pretty-printed). The shape depends
[L242]   // on the run kind: chat carries the conversation turns, completion the prompt.
[L243]   const blob: JlensExport =
[L244]     effectiveKind === 'completion'
[L245]       ? {
[L246]           version: 1,
[L247]           kind: 'completion',
[L248]           modelId: body.modelId,
[L249]           exportedAt: new Date().toISOString(),
[L250]           prompt: body.prompt,
[L251]           meta,
[L252]           tokens,
[L253]           steer: steerExport,
[L254]         }
[L255]       : {
[L256]           version: 1,
[L257]           kind: 'chat',
[L258]           modelId: body.modelId,
[L259]           exportedAt: new Date().toISOString(),
[L260]           messages: chatTurns.map((m) => ({ role: m.role as 'user' | 'assistant', content: m.content })),
[L261]           meta,
[L262]           tokens,
[L263]           steer: steerExport,
[L264]         };
[L265]   const json = JSON.stringify(blob);
[L266]   const uncompressedBytes = Buffer.byteLength(json, 'utf8');
[L267]   if (uncompressedBytes > MAX_JLENS_SHARE_UPLOAD_SIZE_BYTES) {
[L268]     return NextResponse.json(
[L269]       {
[L270]         error: `Shared run is too large (${(uncompressedBytes / (1024 * 1024)).toFixed(1)}MB). The maximum is ${
[L271]           MAX_JLENS_SHARE_UPLOAD_SIZE_BYTES / (1024 * 1024)
[L272]         }MB.`,
[L273]       },
[L274]       { status: 413 },
[L275]     );
[L276]   }
[L277]
[L278]   const shareId = cuid();
[L279]   const region = process.env.AWS_REGION || 'us-east-1';
[L280]   const key = `${JLENS_S3_DIR}/${userId || JLENS_ANONYMOUS_USER_ID}/${shareId}.json`;
[L281]   const url = `https://${NP_GRAPH_BUCKET}.s3.${region}.amazonaws.com/${key}`;
[L282]
[L283]   try {
[L284]     // Store gzipped but as application/json with Content-Encoding: gzip, so the
[L285]     // object is small in S3 yet served back to the browser as plaintext JSON.
[L286]     const compressed = await gzip(json);
[L287]     const s3Client = new S3Client({
[L288]       region,
[L289]       credentials: {
[L290]         accessKeyId: process.env.AWS_ACCESS_KEY_ID || '',
[L291]         secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || '',
[L292]       },
[L293]     });
[L294]     await s3Client.send(
[L295]       new PutObjectCommand({
[L296]         Bucket: NP_GRAPH_BUCKET,
[L297]         Key: key,
[L298]         Body: compressed,
[L299]         ContentType: 'application/json',
[L300]         ContentEncoding: 'gzip',
[L301]       }),
[L302]     );
[L303]   } catch (error) {
[L304]     console.error('Error uploading jlens share to S3:', error);
[L305]     return NextResponse.json({ error: 'Failed to upload shared run' }, { status: 500 });
[L306]   }
[L307]
[L308]   try {
[L309]     await prisma.jlensShare.create({
[L310]       data: {
[L311]         id: shareId,
[L312]         kind: effectiveKind,
[L313]         modelId: body.modelId,
[L314]         url,
[L315]         description: body.description || null,
[L316]         lockedTokens: body.lockedTokens,
[L317]         selectedPositions: body... (truncated)

