[L3] content: import { prisma } from '@/lib/db';
[L4] import { getAllServerHostsForModel } from '@/lib/db/inference-host-source';
[L5] import { ASSET_BASE_URL, DEFAULT_CREATOR_USER_ID, USE_LOCALHOST_INFERENCE } from '@/lib/env';
[L6] import { JlensShareLockedToken } from '@/lib/utils/jlens-share';
[L7] import { JLENS_METADATA_PATH } from '@/lib/utils/lens';
[L8] import { Metadata } from 'next';
[L9] import { notFound, redirect } from 'next/navigation';
[L10] import JlensPageClient, { JlensShareData } from './jlens-page-client';
[L11]
[L12] export async function generateMetadata({ params }: { params: Promise<{ modelId: string }> }): Promise<Metadata> {
[L13]   const { modelId } = await params;
[L14]   const model = await prisma.model.findUnique({ where: { id: modelId }, select: { displayName: true } });
[L15]   const modelName = model?.displayName || modelId;
[L16]
[L17]   const title = `Jacobian Lens – ${modelName}`;
[L18]   const description = `Revealing a Global Workspace in Language Models`;
[L19]
[L20]   return {
[L21]     title,
[L22]     description,
[L23]     openGraph: {
[L24]       title,
[L25]       description,
[L26]       images: [`${ASSET_BASE_URL}${JLENS_METADATA_PATH}`],
[L27]     },
[L28]     twitter: {
[L29]       card: 'summary_large_image',
[L30]       title,
[L31]       description,
[L32]       images: [`${ASSET_BASE_URL}${JLENS_METADATA_PATH}`],
[L33]     },
[L34]   };
[L35] }
[L36]
[L37] export default async function Page({
[L38]   params,
[L39]   searchParams,
[L40] }: {
[L41]   params: Promise<{ modelId: string }>;
[L42]   searchParams: Promise<{ shareId?: string }>;
[L43] }) {
[L44]   const { modelId } = await params;
[L45]   const { shareId } = await searchParams;
[L46]
[L47]   const model = await prisma.model.findUnique({ where: { id: modelId }, select: { id: true } });
[L48]   if (!model) {
[L49]     notFound();
[L50]   }
[L51]
[L52]   // Whether any inference host currently serves this model. When none is
[L53]   // available, the page still renders cached/shared results, but live actions
[L54]   // (sending messages, steering/swapping, toggling the server-side non-word
[L55]   // filter) are gated behind a "model unavailable" notice.
[L56]   // In localhost mode all inference is routed to the local host regardless of
[L57]   // the DB host table, so treat the model as available without a DB lookup.
[L58]   let inferenceAvailable = USE_LOCALHOST_INFERENCE;
[L59]   if (!inferenceAvailable) {
[L60]     try {
[L61]       const hosts = await getAllServerHostsForModel(modelId);
[L62]       inferenceAvailable = hosts.length > 0;
[L63]     } catch {
[L64]       inferenceAvailable = false;
[L65]     }
[L66]   }
[L67]
[L68]   // When `?shareId=` is present, resolve the shared run server-side and pass it
[L69]   // to the page client (which fetches the heavy S3 blob client-side).
[L70]   let share: JlensShareData | null = null;
[L71]   if (shareId) {
[L72]     const row = await prisma.jlensShare.findUnique({
[L73]       where: { id: shareId },
[L74]       include: { user: { select: { name: true } } },
[L75]     });
[L76]     if (!row) {
[L77]       notFound();
[L78]     }
[L79]     // Keep the URL canonical: a share belongs to exactly one model.
[L80]     if (row.modelId !== modelId) {
[L81]       redirect(`/${row.modelId}/jlens?shareId=${shareId}`);
[L82]     }
[L83]
[L84]     // Attribution line shown beneath the description. The default creator's
[L85]     // shares show the description with no attribution; everyone else is credited
[L86]     // (by username if logged in, otherwise as an anonymous sharer).
[L87]     let descriptionAttribution: string | null = null;
[L88]     if (row.description && row.userId !== DEFAULT_CREATOR_USER_ID) {
[L89]       const sharerName = row.userId ? row.user?.name : null;
[L90]       descriptionAttribution = sharerName ? `@${sharerName}` : 'Anonymous';
[L91]     }
[L92]
[L93]     share = {
[L94]       url: row.url,
[L95]       description: row.description,
[L96]       descriptionAttribution,
[L97]       lockedTokens: (row.lockedTokens as unknown as JlensShareLockedToken[]) ?? [],
[L98]       selectedPositions: row.selectedPositions ?? [],
[L99]       activeLensModeTab: row.activeLensModeTab,
[L100]       topN: row.topN,
[L101]       hideNonWordTokens: row.hideNonWordTokens,
[L102]       temperature: row.temperature,
[L103]       numCompletionTokens: row.numCompletionTokens,
[L104]       numPromptTokens: row.numPromptTokens ?? null,
[L105]     };
[L106]   }
[L107]
[L108]   return <JlensPageClient modelId={modelId} share={share} inferenceAvailable={inferenceAvailable} />;
[L109] }

