[L3] content: // Shared constants + types for jlens (Jacobian Lens) share links.
[L4] //
[L5] // A "share" stores the heavy run data (messages, meta, and the full unfiltered
[L6] // per-position token stream) gzipped in S3, and the small UI-restore state in
[L7] // the `JlensShare` DB row. Loading a share fetches the DB row (server-side) for
[L8] // the S3 url + UI state, then the browser downloads + decompresses the S3 blob.
[L9]
[L10] import { LensType } from '@/lib/utils/lens';
[L11]
[L12] // We reuse the existing graph S3 bucket, under a `jlens/` subdirectory.
[L13] export const JLENS_S3_DIR = 'jlens';
[L14] // Anonymous (logged-out) uploads go under `jlens/anonymous/...`.
[L15] export const JLENS_ANONYMOUS_USER_ID = 'anonymous';
[L16]
[L17] // Hard cap on the UNCOMPRESSED share JSON. Enforced before gzip + upload.
[L18] export const MAX_JLENS_SHARE_UPLOAD_SIZE_BYTES = 100 * 1024 * 1024;
[L19]
[L20] // Per-IP/day cap on share creations (mirrors the graph put-request limit).
[L21] export const MAX_JLENS_SHARE_PUT_REQUESTS_PER_DAY = 200;
[L22]
[L23] // Max length of the optional user-supplied share description.
[L24] export const MAX_JLENS_SHARE_DESCRIPTION_LENGTH = 512;
[L25]
[L26] // A locked sidebar predicted-token selection. Keyed by the decoded token STRING
[L27] // (the read-out exposes predicted tokens as strings, not ids), plus its lens
[L28] // type. Position-independent, so robust across re-runs.
[L29] export interface JlensShareLockedToken {
[L30]   key: string;
[L31]   type: LensType;
[L32] }
[L33]
[L34] // The steer configuration saved with a share: the exact decoded token string
[L35] // being steered, its lens type, the model layers the steer was injected at, and
[L36] // the signed strength. The heavy steered token stream + meta live in the S3
[L37] // blob; this small config is also mirrored to `JlensShare` DB columns and is
[L38] // used to re-run the steered read-out (server-side) and re-enter steer mode.
[L39] export interface JlensShareSteer {
[L40]   token: string;
[L41]   type: LensType;
[L42]   layers: number[];
[L43]   strength: number;
[L44]   // When true, the steer ablates (projects out) the readout direction instead
[L45]   // of additively steering — mutually exclusive with strength.
[L46]   ablate: boolean;
[L47]   // Intervention mode: 'steer' (add/suppress) or 'swap' (replace source readout
[L48]   // with `swapToken`). Optional for backward-compat with pre-swap shares.
[L49]   mode?: 'steer' | 'swap';
[L50]   // The free-typed target token for a swap (e.g. " Rugby"). Empty/absent for
[L51]   // plain steers.
[L52]   swapToken?: string;
[L53]   // Whether the intervention was applied to generated tokens too (default
[L54]   // false). Optional for backward-compat with older shares.
[L55]   steerGenerated?: boolean;
[L56] }
[L57]
[L58] // Small UI state restored when opening a shared link. Stored in DB columns
[L59] // (not the S3 blob) so the page can rehydrate without parsing the blob.
[L60] export interface JlensShareUiState {
[L61]   lockedTokens: JlensShareLockedToken[];
[L62]   selectedPositions: number[];
