[L131]   fetchFn: (item: any, signal?: AbortSignal) => Promise<T>,
[L132]   batchSize: number,
[L133]   abortSignal?: AbortSignal,
[L134] ): Promise<T[]> {
[L135]   const results: T[] = [];
[L136]   for (let i = 0; i < items.length; i += batchSize) {
[L137]     if (abortSignal?.aborted) {
[L138]       throw new Error('Request cancelled in fetchInBatches');
[L139]     }
[L140]     const batchItems = items.slice(i, i + batchSize);
[L141]     const batchPromises = batchItems.map((item) => fetchFn(item, abortSignal));
[L142]     const batchResults = await Promise.all(batchPromises);
[L143]     results.push(...batchResults);
[L144]   }
[L145]   return results;
